    {
      "id": "fetchPOData1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Fetch PO Data"
      },
      "inputs": {
        "script": "return {\n  poNumber: \"PO-2024-00742\",\n  vendorName: \"Acme Supplies Ltd.\",\n  totalAmount: 18750.00\n};"
      }
    },
    {
      "id": "poReview1",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "PO Review"
      },
      "inputs": {
        "title": "Purchase Order Review",
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        },
        "priority": "High",
        "schema": {
          "schemaId": "d4e7f812-3a9b-4c62-b1f5-8e2d0a5c3f91",
          "fields": [
            {
              "id": "ponumber",
              "label": "PO Number",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPOData1.output.poNumber"
            },
            {
              "id": "vendorname",
              "label": "Vendor Name",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchPOData1.output.vendorName"
            },
            {
              "id": "totalamount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchPOData1.output.totalAmount"
            },
            {
              "id": "decision",
              "label": "Decision",
              "type": "string",
              "direction": "output",
              "variable": "vars.decision",
              "required": true
            },
            {
              "id": "notes",
              "label": "Notes",
              "type": "string",
              "direction": "output",
              "variable": "vars.notes",
              "required": false
            }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true,  "action": "Continue" },
            { "id": "reject",  "name": "Reject",  "type": "string", "isPrimary": false, "action": "End" }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "decision": { "type": "string" },
            "notes":    { "type": "string" },
            "Action":   { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "routeDecision1",
      "type": "core.logic.condition",
      "typeVersion": "1.0",
      "display": {
        "label": "Route on Decision"
      },
      "inputs": {
        "conditions": [
          {
            "expression": "=js:$vars.poReview1.status === \"Approve\""
          }
        ]
      }
    },
    {
      "id": "logApproval1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log PO Approved"
      },
      "inputs": {
        "script": "const decision = $vars.poReview1.output.decision;\nconst notes = $vars.poReview1.output.notes;\nconsole.log(\"PO approved\");\nconsole.log(\"Decision:\", decision);\nif (notes) console.log(\"Notes:\", notes);\nreturn { approved: true, message: \"PO approved\" };"
      }
    },
    {
      "id": "end1",
      "type": "core.logic.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End (Rejected)"
      }
    }
  ],
  "edges": [
    {
      "id": "start-output-fetchPOData1-input",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "fetchPOData1",
      "targetPort": "input"
    },
    {
      "id": "fetchPOData1-output-poReview1-input",
      "sourceNodeId": "fetchPOData1",
      "sourcePort": "output",
